mapper.select:
select message_id, user_id, sender_id, sender_name, title, content, msg_type, is_read, read_time, related_id, related_type, create_time
from ee_message

     and user_id = #{userId}
     and msg_type = #{msgType}
     and is_read = #{isRead}
     and title like concat('%', #{title}, '%')

order by create_time desc

mapper.update:
update ee_message
is_read = #{isRead}, read_time = #{readTime},
where message_id = #{messageId}
